'use strict';

// Zero-dependency .env loader and app configuration.

const fs = require('node:fs');
const path = require('node:path');

/**
 * Parse the text of a .env file into a plain object.
 * Supports: blank lines, `#` comments, optional `export ` prefix,
 * single/double-quoted values, and inline `#` comments on unquoted values.
 * Splits only on the first `=`, so values may contain `=`.
 */
function parseEnv(text) {
  const result = {};
  const lines = text.replace(/^﻿/, '').split(/\r?\n/);

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eq = line.indexOf('=');
    if (eq === -1) continue;

    const key = line.slice(0, eq).replace(/^export\s+/, '').trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) continue;

    let value = line.slice(eq + 1).trim();
    const quote = value[0];
    if ((quote === '"' || quote === "'") && value.length >= 2 && value.endsWith(quote)) {
      value = value.slice(1, -1);
      if (quote === '"') value = value.replace(/\\n/g, '\n');
    } else {
      const hash = value.search(/\s#/);
      if (hash !== -1) value = value.slice(0, hash).trim();
    }

    result[key] = value;
  }

  return result;
}

/**
 * Read and parse a .env file. Returns {} if the file does not exist.
 */
function loadEnvFile(filePath = path.join(__dirname, '.env')) {
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return {};
    throw err;
  }
  return parseEnv(text);
}

/**
 * Build the config object. Real environment variables take precedence
 * over values from the .env file.
 */
function loadConfig(filePath, env = process.env) {
  const fileVars = loadEnvFile(filePath);
  const get = (key) => (env[key] !== undefined ? env[key] : fileVars[key]);

  return Object.freeze({
    // Stripe secret API key — server-side only, used to create charges/customers.
    stripeSecretKey: get('STRIPE_SECRET_KEY'),
    // OpenAI API key — authenticates requests to the OpenAI API.
    openaiApiKey: get('OPENAI_API_KEY'),
    // GitHub personal access token — used for GitHub API calls.
    githubToken: get('GITHUB_TOKEN'),
    // AWS access key ID — identifies the IAM user (pair with a secret access key).
    awsAccessKeyId: get('AWS_ACCESS_KEY_ID'),
    // PostgreSQL connection string: {{EXAMPLE_DB_URL}}
    databaseUrl: get('DATABASE_URL'),
  });
}

module.exports = { parseEnv, loadEnvFile, loadConfig };

