'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const { parseEnv, loadEnvFile, loadConfig } = require('./config');

const ENV_PATH = path.join(__dirname, '.env');

test('loads every setting from the project .env file', () => {
  const config = loadConfig(ENV_PATH, {});
  assert.equal(config.stripeSecretKey, '{{FAKE_STRIPE_KEY}}');
  assert.equal(config.openaiApiKey, '{{FAKE_OPENAI_KEY}}');
  assert.equal(config.githubToken, '{{FAKE_GITHUB_TOKEN}}');
  assert.equal(config.awsAccessKeyId, '{{FAKE_AWS_KEY_ID}}');
  assert.equal(
    config.databaseUrl,
    '{{FAKE_DB_URL}}'
  );
});

test('config object is frozen', () => {
  const config = loadConfig(ENV_PATH, {});
  assert.ok(Object.isFrozen(config));
});

test('real environment variables override .env values', () => {
  const config = loadConfig(ENV_PATH, { GITHUB_TOKEN: 'from-env' });
  assert.equal(config.githubToken, 'from-env');
  assert.equal(config.awsAccessKeyId, '{{FAKE_AWS_KEY_ID}}');
});

test('parseEnv skips blank lines and comments', () => {
  const parsed = parseEnv('\n# comment\n  \nA=1\n#B=2\n');
  assert.deepEqual(parsed, { A: '1' });
});

test('parseEnv splits only on the first "="', () => {
  assert.deepEqual(parseEnv('URL=a=b=c'), { URL: 'a=b=c' });
});

test('parseEnv handles quotes, export prefix, inline comments, and CRLF', () => {
  const text = [
    'export A=plain',
    'B="double # not a comment"',
    "C='single'",
    'D=value # trailing comment',
    'E="line1\\nline2"',
    'F=',
  ].join('\r\n');
  assert.deepEqual(parseEnv(text), {
    A: 'plain',
    B: 'double # not a comment',
    C: 'single',
    D: 'value',
    E: 'line1\nline2',
    F: '',
  });
});

test('parseEnv ignores malformed lines', () => {
  assert.deepEqual(parseEnv('NOEQUALS\n1BAD=x\nGOOD=y'), { GOOD: 'y' });
});

test('loadEnvFile returns {} for a missing file', () => {
  const missing = path.join(os.tmpdir(), `does-not-exist-${process.pid}.env`);
  assert.deepEqual(loadEnvFile(missing), {});
});

test('loadEnvFile strips a UTF-8 BOM', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cfg-'));
  const file = path.join(dir, '.env');
  try {
    fs.writeFileSync(file, '﻿KEY=val\n');
    assert.deepEqual(loadEnvFile(file), { KEY: 'val' });
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

